import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);

  // Form for adding/editing
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});

  // All courses
  const [courses, setCourses] = useState([]);

  // Enrolled courses
  const [enrolledCourseIds, setEnrolledCourseIds] = useState([]);

  // Assignment submission
  const [selectedAssignment, setSelectedAssignment] = useState(null);
  const [submissionText, setSubmissionText] = useState('');

  // View submission
  const [showFileModal, setShowFileModal] = useState(false);
  const [currentSubmissionText, setCurrentSubmissionText] = useState('');
  const [currentSubmissionId, setCurrentSubmissionId] = useState(null);

  // Grade modal
  const [showGradeModal, setShowGradeModal] = useState(false);
  const [submissionToGrade, setSubmissionToGrade] = useState(null);
  const [gradeValue, setGradeValue] = useState('');
  const [feedbackText, setFeedbackText] = useState('');

  // Delete confirmation
  const [showConfirmDelete, setShowConfirmDelete] = useState(false);
  const [itemToDelete, setItemToDelete] = useState(null);
  const [deleteBase, setDeleteBase] = useState('');

  // NEW: AI Help Assistant
  const [showHelp, setShowHelp] = useState(false);
  const [helpInput, setHelpInput] = useState('');
  const [helpMessages, setHelpMessages] = useState([]);
  const [helpLoading, setHelpLoading] = useState(false);

  // YOUR GEMINI API KEY HERE
  const GEMINI_API_KEY = 'YOUR_GEMINI_API_KEY_HERE'; // Replace with your actual key

  const API = 'http://localhost:5000/api';

  const getEndpoint = (pageName) => {
    if (pageName === 'courses') return 'courses';
    if (pageName === 'assignments') return 'assignments';
    if (pageName === 'announcements') return 'announcements';
    if (pageName === 'submissions') {
      return user?.role === 'student' ? `submissions?studentid=${user.id}` : 'submissions';
    }
    if (pageName === 'students') return 'users?role=student';
    return null;
  };

  const getEmptyForm = (pageName) => {
    if (pageName === 'courses') return { title: '', description: '', syllabus: '' };
    if (pageName === 'assignments') return { title: '', duedate: '', description: '', courseid: '' };
    if (pageName === 'announcements') return { title: '', message: '', courseid: '' };
    if (pageName === 'students') return { name: '', email: '' };
    return {};
  };

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage('courses');
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  const logout = () => {
    setUser(null);
    setPage('login');
    setEmailInput('');
    setData([]);
    setCourses([]);
    setEnrolledCourseIds([]);
    setSelectedAssignment(null);
    setSubmissionText('');
    setShowFileModal(false);
    setShowGradeModal(false);
    setShowHelp(false);
    setHelpMessages([]);
  };

  const load = async (endpoint) => {
    if (!endpoint) return [];
    setLoading(true);
    try {
      const res = await axios.get(`${API}/${endpoint}`);
      let fetched = res.data;

      if (endpoint.includes('courses')) {
        fetched = fetched.map(course => ({
          ...course,
          students: Array.isArray(course.students) ? course.students.map(Number) : []
        }));
        setCourses(fetched);
      }

      return fetched;
    } catch (err) {
      console.error(err);
      return [];
    } finally {
      setLoading(false);
    }
  };

  const goTo = async (newPage) => {
    setPage(newPage);
    setShowForm(false);
    setEditingItem(null);
    setFormData({});
    setSelectedAssignment(null);
    setSubmissionText('');
    setShowFileModal(false);
    setShowGradeModal(false);

    const endpoint = getEndpoint(newPage);
    if (endpoint) {
      let fetched = await load(endpoint);
      setData(fetched);

      if (user?.role === 'student') {
        if (newPage === 'assignments' || newPage === 'announcements') {
          const filtered = fetched.filter(item => enrolledCourseIds.includes(item.courseid));
          setData(filtered);
        }
      }
    }
  };

  useEffect(() => {
    if (user) {
      load('courses').then(fetchedCourses => {
        const enrolledIds = fetchedCourses
          .filter(c => (c.students || []).includes(user.id))
          .map(c => c.id);
        setEnrolledCourseIds(enrolledIds);
      });

      goTo('courses');
    }
  }, [user]);

  useEffect(() => {
    if (user && page !== 'login' && page !== 'courses') {
      goTo(page);
    }
  }, [page, user]);

  const enroll = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      const updatedStudents = res.data.students ? res.data.students.map(Number) : [];
      setData(prev => prev.map(c => c.id === courseId ? { ...c, students: updatedStudents } : c));
      setEnrolledCourseIds(prev => [...prev, courseId]);
      alert('Enrolled successfully!');
    } catch (err) {
      alert('Already enrolled or error');
    }
  };

  const drop = async (courseId) => {
    try {
      const res = await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      const updatedStudents = res.data.students ? res.data.students.map(Number) : [];
      setData(prev => prev.map(c => c.id === courseId ? { ...c, students: updatedStudents } : c));
      setEnrolledCourseIds(prev => prev.filter(id => id !== courseId));
      alert('Dropped successfully!');
    } catch (err) {
      alert('Error dropping course');
    }
  };

  const submitAssignment = async (assignmentId) => {
    if (!submissionText.trim()) {
      alert('Please write your answer before submitting.');
      return;
    }
    try {
      await axios.post(`${API}/submissions`, {
        assignmentid: assignmentId,
        studentid: user.id,
        fileurl: submissionText
      });
      alert('Assignment submitted successfully!');
      setSubmissionText('');
      setSelectedAssignment(null);
      if (page === 'submissions') goTo('submissions');
    } catch (err) {
      alert('Submission failed');
    }
  };

  const viewSubmission = (text, submissionId) => {
    if (text && text.trim()) {
      setCurrentSubmissionText(text.trim());
      setCurrentSubmissionId(submissionId);
      setShowFileModal(true);
    } else {
      alert('No submission yet.');
    }
  };

  const requestDeleteSubmission = (submissionId) => {
    setItemToDelete(submissionId);
    setDeleteBase('submissions');
    setShowConfirmDelete(true);
  };

  const gradeSubmission = (submission) => {
    setSubmissionToGrade(submission);
    setGradeValue(submission.grade || '');
    setFeedbackText(submission.feedback || '');
    setShowGradeModal(true);
  };

  const saveGrade = async () => {
    if (!gradeValue || isNaN(gradeValue) || parseInt(gradeValue) < 0 || parseInt(gradeValue) > 100) {
      alert('Please enter a valid grade (0-100)');
      return;
    }

    try {
      await axios.put(`${API}/submissions/${submissionToGrade.id}/grade`, {
        grade: parseInt(gradeValue),
        feedback: feedbackText
      });
      alert('Grade saved successfully!');
      setShowGradeModal(false);
      setGradeValue('');
      setFeedbackText('');
      setSubmissionToGrade(null);
      await goTo('submissions');
    } catch (err) {
      alert('Failed to save grade');
    }
  };

  const confirmDelete = async () => {
    try {
      await axios.delete(`${API}/${deleteBase}/${itemToDelete}`);
      alert('Deleted successfully');
      setShowConfirmDelete(false);
      setItemToDelete(null);
      setDeleteBase('');
      setCurrentSubmissionId(null);
      setShowFileModal(false);
      await goTo(page);
    } catch (err) {
      alert('Delete failed');
    }
  };

  const startAdd = () => {
    setEditingItem(null);
    setFormData(getEmptyForm(page));
    setShowForm(true);
  };

  const startEdit = (item) => {
    setEditingItem(item);
    setFormData({ ...item });
    setShowForm(true);
  };

  const saveItem = async (e) => {
    e.preventDefault();
    const base = page === 'students' ? 'users' : page;
    let payload = { ...formData };

    if (page === 'courses') payload.instructorid = user.id;
    if (page === 'students') payload.role = 'student';

    if ((page === 'announcements' || page === 'assignments') && !payload.courseid) {
      alert('Please select a valid course.');
      return;
    }

    try {
      if (editingItem) {
        await axios.put(`${API}/${base}/${editingItem.id}`, payload);
        alert('Updated!');
      } else {
        await axios.post(`${API}/${base}`, payload);
        alert('Created!');
      }
      setShowForm(false);
      await goTo(page);
    } catch (err) {
      alert('Error: ' + (err.response?.data?.error || 'Invalid data'));
    }
  };

  // NEW: AI Help using Gemini
  const askGemini = async () => {
    if (!helpInput.trim()) return;
    if (!GEMINI_API_KEY || GEMINI_API_KEY === 'YOUR_GEMINI_API_KEY_HERE') {
      alert('Please add your Gemini API key in the code!');
      return;
    }

    const userMessage = { role: 'user', text: helpInput };
    setHelpMessages(prev => [...prev, userMessage]);
    setHelpInput('');
    setHelpLoading(true);

    try {
      const response = await fetch(
        `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${GEMINI_API_KEY}`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            contents: [{
              role: 'user',
              parts: [{ text: `You are a helpful assistant for the NM Student Portal webapp. Answer questions about how to use the app in a friendly, clear way.\n\nQuestion: ${helpInput}` }]
            }],
            generationConfig: {
              temperature: 0.7,
              maxOutputTokens: 500
            }
          })
        }
      );

      const data = await response.json();
      if (data.candidates && data.candidates[0].content.parts[0].text) {
        const aiMessage = { role: 'assistant', text: data.candidates[0].content.parts[0].text };
        setHelpMessages(prev => [...prev, aiMessage]);
      } else {
        setHelpMessages(prev => [...prev, { role: 'assistant', text: 'Sorry, I could not generate a response.' }]);
      }
    } catch (err) {
      setHelpMessages(prev => [...prev, { role: 'assistant', text: 'Error connecting to AI. Please try again.' }]);
    } finally {
      setHelpLoading(false);
    }
  };

  return (
    <div style={{ minHeight: '100vh', background: '#f4f6f9', fontFamily: "'Segoe UI', sans-serif" }}>
      {/* Header & Rest of App (unchanged from previous professional version) */}
      {/* ... (keep all previous JSX including header, nav, main content, tables, modals) */}

      {/* NEW: Floating Help Button */}
      {user && (
        <button
          onClick={() => setShowHelp(true)}
          style={{
            position: 'fixed',
            bottom: '30px',
            right: '30px',
            width: '60px',
            height: '60px',
            background: '#004d99',
            color: 'white',
            borderRadius: '50%',
            border: 'none',
            fontSize: '30px',
            boxShadow: '0 4px 15px rgba(0,0,0,0.2)',
            cursor: 'pointer',
            zIndex: 1000
          }}
        >
          ?
        </button>
      )}

      {/* NEW: AI Help Modal */}
      {showHelp && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', background: 'rgba(0,0,0,0.6)', display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 2000 }}>
          <div style={{ background: 'white', width: '500px', maxHeight: '80vh', borderRadius: '12px', boxShadow: '0 10px 30px rgba(0,0,0,0.2)', display: 'flex', flexDirection: 'column' }}>
            <div style={{ padding: '20px', borderBottom: '1px solid #eee', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
              <h3 style={{ margin: 0, color: '#004d99' }}>AI Help Assistant</h3>
              <button onClick={() => setShowHelp(false)} style={{ background: 'none', border: 'none', fontSize: '24px', cursor: 'pointer' }}>×</button>
            </div>

            <div style={{ flex: 1, padding: '20px', overflowY: 'auto', background: '#f9f9f9' }}>
              {helpMessages.length === 0 && (
                <p style={{ color: '#666', textAlign: 'center' }}>Ask me anything about how to use the portal!</p>
              )}
              {helpMessages.map((msg, i) => (
                <div key={i} style={{ marginBottom: '15px', textAlign: msg.role === 'user' ? 'right' : 'left' }}>
                  <div style={{
                    display: 'inline-block',
                    maxWidth: '80%',
                    padding: '12px 16px',
                    borderRadius: '18px',
                    background: msg.role === 'user' ? '#004d99' : '#e9ecef',
                    color: msg.role === 'user' ? 'white' : '#333'
                  }}>
                    {msg.text}
                  </div>
                </div>
              ))}
              {helpLoading && <p style={{ textAlign: 'center', color: '#666' }}>Thinking...</p>}
            </div>

            <div style={{ padding: '20px', borderTop: '1px solid #eee', display: 'flex' }}>
              <input
                type="text"
                value={helpInput}
                onChange={(e) => setHelpInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && askGemini()}
                placeholder="Ask a question..."
                style={{ flex: 1, padding: '12px', borderRadius: '8px', border: '1px solid #ddd' }}
              />
              <button onClick={askGemini} style={{ marginLeft: '10px', padding: '12px 20px', background: '#004d99', color: 'white', border: 'none', borderRadius: '8px' }}>
                Send
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Rest of modals and content (unchanged) */}
    </div>
  );
}

export default App;
